a=[[1]*w for _ in range(h)]
zeros={0:[1,3,4,6,7,9,11,12,14,16,17],1:[17],2:[1,17],3:[1,17],4:[1,17],6:[1,17],7:[1,17],8:[1,17],9:[17],10:[17],11:[1,4,5,6,7,8,12,14,15,16,17]}
