 for x,y in zip(ps,ps[1:]):
  for c in range(x+1,y):o[r][c]=2
for c in range(w):
 ps=[r for r in range(h) if a[r][c]==0]
 for x,y in zip(ps,ps[1:]):
  for r in range(x+1,y):
   if o[r][c]==1:o[r][c]=2
